/**
 * One row from `GET /v1/liquidity-pools/{id}/activity` — **one operation
 * against this pool**, not one transaction (task 0491, issue #371).
 *
 * The transaction-level fields the retired `/transactions` shape carried
 * (`fee_charged`, `operation_count`, `has_soroban`, `successful`,
 * `operation_types`) are gone: the first three describe the transaction, not
 * this row, and repeating them per operation invites reading a transaction
 * fee as an operation fee. `operation_types` is replaced by `event`, which is
 * what it was approximating.
 */
export type PoolActivityItem = {
  /**
   * Signed from the POOL's perspective: positive entered the pool, negative
   * left it. Raw stroops as a decimal string, scaled by 7 at render like
   * every other amount here — a JSON number is a double in the browser, so
   * a leg above 2^53 stroops would silently lose digits.
   *
   * The sign is the payload, not decoration: it is what names `event`, so
   * the frontend must not take an absolute value before deciding direction.
   * `null` on both legs in the malformed case above.
   */
  amount_a?: string | null;
  amount_b?: string | null;
  /**
   * The operation's 1-based position in its transaction (Horizon's
   * `application_order`), and the `#op-N` anchor on the transaction detail
   * page this row links to (task 0482).
   */
  application_order: number;
  created_at: string;
  event?: null | PoolEvent;
  ledger_sequence: number;
  /**
   * How many pools the WHOLE operation crossed — `length(pool_ids)` from
   * the same appearance seek that resolves the source account. `1` for
   * every deposit/withdrawal (an LP op declares exactly one pool) and for
   * a single-hop trade; `> 1` marks this row as one hop of a longer path
   * payment, whose full route lives on the op's detail page. `null` only
   * when the appearance row is missing — unknown, never guessed to `1`.
   */
  pools_crossed?: number | null;
  /**
   * Who performed THIS OPERATION — the operation's own source account when
   * it declares one, otherwise the transaction's, which is what an absent
   * `Operation.sourceAccount` means in the XDR.
   *
   * Not simply the transaction's source: on a per-operation row that names
   * the wrong account whenever the two differ, which on prod is 41% of
   * operations in a recent ledger window. The retired `/transactions` shape
   * could only ever carry the transaction's, since its row WAS one.
   */
  source_account: string;
  /**
   * Transaction hash (64-char lowercase hex). NOT unique across rows — a
   * transaction running several operations against this pool appears once
   * per operation, so a row key needs `application_order` too.
   */
  transaction_hash: string;
};

/**
 * One leg of an LP's asset pair. Surfaces both the decoded
 * `asset_type_name` (SQL `asset_type_name()`) and the raw `asset_type`
 * SMALLINT — same contract as `assets/dto::AssetItem`.
 *
 * Linkable identifiers (task 0263 / F-K-9). All link targets are the
 * **asset detail page** (`/assets/...`) — `parse_asset_id` is polymorphic
 * and accepts both C-strkey (SAC) and `code-issuer` composite, so all
 * non-native legs resolve to the same asset row.
 *
 * * `asset_type == 0` — native XLM; routes to `/assets/native`, the
 * reserved token for the classic XLM singleton (it has no `code-issuer`
 * identity to compose).
 * * `contract_id` — C-strkey of the SAC mirror for a classic credit OR
 * native leg (populated when the leg's `(asset_code, issuer)`
 * classic_credit / native `assets` row carries a deployed SAC facet —
 * `sac_contract_id` resolving a `soroban_contracts.contract_id`,
 * ADR 0051). `None` for legs without a deployed SAC mirror.
 *
 * Native legs were excluded from this until task 0470. The exclusion was
 * deliberate (`a19ac8f6`) and its reason was Postgres parity — PG returned
 * NULL there. Postgres is retired, and the same native `assets` row
 * already publishes that SAC as `sac_contract_id` on `/v1/assets/native`
 * and in the assets list, which the frontend renders. Withholding it here
 * alone made one asset describe itself two ways depending on the endpoint.
 * Pool legs only carry XDR `AssetType` (native /
 * credit_alphanum4 / credit_alphanum12) per `0006_liquidity_pools.sql`,
 * so SAC / Soroban legs are not directly representable here;
 * `contract_id` surfaces the SAC mirror look-up so the FE can
 * route to the asset detail page via `/assets/${contract_id}`.
 * * `issuer` + `asset_code` (classic credit, no SAC mirror) — FE
 * routes to `/assets/${asset_code}-${issuer}` (composite form
 * accepted by `parse_asset_id`).
 */
export type PoolAssetLeg = {
  asset_code?: string | null;
  /**
   * Raw SMALLINT, XDR `AssetType`: 0=native, 1=credit_alphanum4,
   * 2=credit_alphanum12. Not the `assets.asset_type` family domain.
   */
  asset_type: number;
  /**
   * Label in the **XDR `AssetType`** vocabulary — this is a pool LEG, and
   * leg types come from `liquidity_pools.asset_a_type`/`asset_b_type`,
   * which store the protocol discriminant: `native` |
   * `credit_alphanum4` | `credit_alphanum12`. `null` only on schema drift.
   * (Task 0496 mirror: this doc used to carry the `AssetFamily` legend,
   * declaring 2 "retired" — while 54 456 production legs carry
   * 2 = `credit_alphanum12`.)
   */
  asset_type_name?: string | null;
  /**
   * C-strkey of the deployed SAC mirror for the leg's `(asset_code, issuer)`
   * classic_credit / native asset (ADR 0051 — resolved via the row's
   * `sac_contract_id` facet). `None` only when no SAC is deployed for that
   * asset. Native XLM has one, and reports it here (task 0470) exactly as
   * `/v1/assets/native` already did.
   */
  contract_id?: string | null;
  /**
   * Asset icon URL, resolved from `asset_enrichment` (ADR 0050) so pool
   * avatars render the same icon as the assets list. Until task 0310 this
   * read the dead `assets.icon_url` column, which was never populated —
   * every leg icon came back `None`. Still `None` for assets without an
   * enriched icon — the FE falls back to the asset-code initial.
   */
  icon_url?: string | null;
  issuer?: string | null;
};

/**
 * What an operation did to the pool, named by the SIGN PAIR of its two legs
 * and nothing else — `lp_operation_amounts.amount` is signed from the pool's
 * perspective, so `+/+` is a deposit, `-/-` a withdrawal and `+/-` a trade.
 * There is no operation-type column to read and no join to `operations`.
 *
 * Classified in SQL rather than here, because the same expression is the
 * `filter[event]` predicate: two classifiers would eventually disagree, and
 * the one the user sees must be the one the filter used. This deliberately
 * reverses the client-side policy the retired `/transactions` shape carried.
 */
export type PoolEvent = 'trade' | 'deposit' | 'withdrawal';

/**
 * One pool row returned by the list endpoint. Shape pinned to canonical
 * SQL `18_get_liquidity_pools_list.sql`. Pools without a fresh snapshot
 * in the freshness window come back with `null` for every dynamic field
 * (`reserve_a`, `reserve_b`, `total_shares`, `tvl`, `volume`,
 * `fee_revenue`, `latest_snapshot_*`); frontend renders these as "stale".
 */
export type PoolItem = {
  asset_a: PoolAssetLeg;
  asset_b: PoolAssetLeg;
  created_at_ledger: number;
  fee_bps: number;
  /**
   * `fee_bps / 100` as decimal string. Conversion done server-side so
   * the frontend can render directly (frontend §6.13/§6.14).
   */
  fee_percent: string;
  /**
   * USD, decimal string rounded to cents. **Detail endpoint only.**
   * `volume × fee_bps / 10000` — the pool's 24h fee estimate.
   */
  fee_revenue?: string | null;
  latest_snapshot_at?: string | null;
  latest_snapshot_ledger?: number | null;
  /**
   * Count of active liquidity providers (`lp_positions WHERE shares > 0`).
   * Computed from the live table — not dependent on the snapshot
   * freshness window, so it is populated even on stale pools (where
   * `tvl`/`volume`/`fee_revenue` are NULL).
   */
  participant_count: number;
  /**
   * SEP-23 strkey (`L...`, 56 chars). DB stores `BYTEA(32)` per ADR
   * 0024; the handler encodes to strkey at the response boundary so
   * the wire shape matches the Stellar ecosystem canonical form
   * (CAP-38 / SEP-23).
   */
  pool_id: string;
  reserve_a?: string | null;
  reserve_b?: string | null;
  total_shares?: string | null;
  /**
   * USD, decimal string rounded to cents (task 0199 compute-at-read).
   * Populated on **both** the list (Phase A2, one batched price lookup
   * per page) and the detail endpoint. `tvl` = latest reserves × each
   * leg's last hourly USD close (`prices.price_usd_series_1h`, ≤ ~2h
   * stale); `null` unless both legs price (never a one-leg partial) —
   * untracked assets and stale pools read `null`.
   */
  tvl?: string | null;
  /**
   * USD, decimal string rounded to cents. **Detail endpoint only.**
   * Gross trade volume over the last 24h (`gross_volume_a` sum) priced
   * at the leg-A last hourly close; `null` when the pool is unpriceable.
   */
  volume?: string | null;
};

/**
 * The classic asset a SAC contract is the contract-side facet of (ADR 0051,
 * task 0441). `None` on non-SAC contracts — and on the rare SAC with no
 * resolvable `asset_sac` facet row (2 of 3,946 on prod), where the frontend
 * keeps the bare SAC badge. Native XLM is `asset_code: null, issuer: null`;
 * a classic asset always carries both (an asset code alone is ambiguous —
 * prod holds many issuers of "USDC").
 */
export type SacAsset = {
  /**
   * Classic asset code (e.g. `USDC`); `null` = native XLM.
   */
  asset_code?: string | null;
  /**
   * Issuer account G-strkey; `null` = native XLM.
   */
  issuer?: string | null;
};

/**
 * Per-entity buckets. Empty buckets are omitted from the JSON output
 * via `skip_serializing_if` — frontend treats absent and empty array
 * identically, and dropping empties keeps the dropdown payload tight
 * when a typed `?type=` filter narrows results to a single bucket.
 */
export type SearchGroups = {
  accounts?: Array<SearchHit>;
  assets?: Array<SearchHit>;
  contracts?: Array<SearchHit>;
  nfts?: Array<SearchHit>;
  pools?: Array<SearchHit>;
  transactions?: Array<SearchHit>;
};

/**
 * Single search row. Same shape across every entity bucket.
 *
 * `identifier` is the canonical human-shown id (hex hash for
 * transactions, strkey `L…` for pools, StrKey for accounts /
 * contracts, asset code for assets, name for NFTs). It is the routing
 * key too for every type whose display id IS routable (transaction,
 * account, contract, pool). The two exceptions carry a separate routing
 * payload because their display id is NOT routable:
 *
 * - `asset`: `identifier` is the asset code (not unique / not routable);
 * `route_token` carries the canonical `/assets/:id` token (contract
 * StrKey | `CODE-ISSUER` | `native`), mirroring `canonical_id` in
 * `assets/handlers.rs`.
 * - `nft`: identity is the composite `(contract_id, token_id)` per task
 * 0264 / ADR 0030 — the two fields below carry it for routing.
 *
 * `successful` and `last_activity_at` are populated only for
 * `entity_type = transaction` today — joined from the partitioned
 * `transactions` table via `(hash, created_at)` for partition pruning.
 * Other entity types pass `None` for both until follow-up enrichment
 * adds per-entity last-activity joins. The frontend renders a
 * status chip + relative timestamp on the right side of the row
 * whenever these fields are present.
 */
export type SearchHit = {
  /**
   * NFT composite routing key. Populated only when
   * `entity_type = nft`; `None` for every other bucket.
   */
  contract_id?: string | null;
  entity_type: EntityType;
  identifier: string;
  label: string;
  last_activity_at?: string | null;
  /**
   * Canonical `/assets/:id` routing token for `asset` hits; `None` for
   * every other type (they route on `identifier`). See the struct doc.
   */
  route_token?: string | null;
  successful?: boolean | null;
  /**
   * NFT composite routing key. Populated only when
   * `entity_type = nft`; `None` for every other bucket.
   */
  token_id?: string | null;
};

/**
 * Results payload — six entity-typed buckets, each capped at the
 * per-group `limit` chosen by the caller (default 10, ceiling 50).
 *
 * FE decides "singleton → navigate directly" by inspecting
 * `groups`: when the total row count across all buckets is exactly
 * 1 and `routeForHit(singleton)` resolves, the FE navigates to the
 * detail page; otherwise it renders the dropdown / Results page.
 */
export type SearchResults = {
  groups: SearchGroups;
};

/**
 * Single signature on a transaction envelope.
 */
export type SignatureDto = {
  /**
   * 4-byte hint (lowercase hex, 8 chars).
   */
  hint: string;
  /**
   * Signature bytes (lowercase hex).
   */
  signature: string;
};

/**
 * DB-sourced light slice for the transaction detail endpoint.
 *
 * Composed with `E3HeavyFields` via `merge_e3_response` (task 0150). All
 * XDR-sourced fields (memo, result_code, signatures, events, operation
 * details, envelope_xdr/result_xdr, operation_tree) live in `heavy`.
 */
export type TransactionDetailLight = {
  /**
   * 1-based position of this transaction within its ledger.
   */
  application_order: number;
  created_at: string;
  /**
   * Fee charged, in raw stroops. Native (XLM) is always 7 decimals, so
   * there is no `decimals` field — the frontend scales by 1e7.
   */
  fee_charged: number;
  has_soroban: boolean;
  /**
   * Transaction hash (64-char lowercase hex).
   */
  hash: string;
  /**
   * Inner-transaction hash (64-char hex) for fee-bump envelopes, `null` otherwise.
   */
  inner_tx_hash?: string | null;
  ledger_sequence: number;
  operation_count: number;
  operations: Array<OperationItem>;
  /**
   * `true` when the XDR parser encountered an error for this transaction.
   */
  parse_error: boolean;
  /**
   * Accounts touched by this transaction. Populated only when
   * `heavy_fields_status = "unavailable"`; otherwise `[]` and consumers
   * should rely on the heavy block.
   */
  participants: Array<string>;
  /**
   * Soroban event appearance index rows. Same fallback semantics as
   * `participants`. Full topics + data live in `heavy.contract_events`.
   */
  soroban_events: Array<EventAppearanceItem>;
  /**
   * Soroban invocation appearance index rows. Same fallback semantics
   * as `participants`. Full call hierarchy lives in `heavy.operation_tree`.
   */
  soroban_invocations: Array<InvocationAppearanceItem>;
  /**
   * `null` for Variant A `parse_error` transactions whose envelope
   * could not be decoded (lore-0209).
   */
  source_account?: string | null;
  /**
   * The source account's on-chain `home_domain` (SEP-1 anchor domain),
   * `null` when it sets none. The frontend asks that domain for the SEP-2
   * federated address it claims for this account (task 0443, issue #363).
   */
  source_account_home_domain?: string | null;
  successful: boolean;
};

/**
 * Slim transaction row returned in the list endpoint.
 */
export type TransactionListItem = {
  /**
   * 1-based position of this transaction within its ledger.
   */
  application_order: number;
  created_at: string;
  /**
   * Fee charged, in raw stroops. Native (XLM) is always 7 decimals, so
   * there is no `decimals` field — the frontend scales by 1e7.
   */
  fee_charged: number;
  /**
   * `true` when the transaction touched at least one Soroban contract
   * (root invocation, nested call, or event emission).
   */
  has_soroban: boolean;
  /**
   * Transaction hash (64-char lowercase hex).
   */
  hash: string;
  /**
   * Inner-transaction hash (64-char hex) for fee-bump envelopes, `null` otherwise.
   */
  inner_tx_hash?: string | null;
  ledger_sequence: number;
  operation_count: number;
  /**
   * All distinct operation type names in the transaction
   * (e.g. `["INVOKE_HOST_FUNCTION", "PAYMENT"]`).
   */
  operation_types: Array<string>;
  /**
   * `null` for Variant A `parse_error` transactions whose envelope
   * could not be decoded (lore-0209). Always populated for ordinary
   * (successful or failed-but-decoded) transactions.
   */
  source_account?: string | null;
  successful: boolean;
};

/**
 * Common shape for contract events and diagnostic events.
 */
export type XdrEventDto = {
  /**
   * Contract address (StrKey) that emitted the event, if any.
   */
  contract_id?: string | null;
  /**
   * Decoded event data payload.
   */
  data: unknown;
  /**
   * Event index within the transaction (zero-based).
   */
  event_index: number;
  /**
   * `"contract"`, `"system"`, or `"diagnostic"`.
   */
  event_type: string;
  /**
   * Zero-based envelope position of the operation that emitted this event
   * (CAP-67 V4 per-operation container only; `None` for tx-level,
   * diagnostic and pre-Protocol-23 events). Matches
   * `XdrOperationDto.application_order - 1`.
   */
  op_index?: number | null;
  /**
   * CAP-67 `TransactionEvent.stage` — `"before_all_txs"`, `"after_tx"` or
   * `"after_all_txs"`. The protocol's only statement of when a tx-level
   * event fired, and the reason `event_index` must not be read as a
   * timeline: the fee refund is numbered ahead of the operation it
   * refunds. Observed values on mainnet are `before_all_txs` for the charge
   * and `after_all_txs` for the refund; `after_tx` exists in the protocol
   * and is passed through unchanged if it appears. `None` for per-operation, diagnostic and
   * pre-Protocol-23 events, which carry no stage.
   */
  stage?: string | null;
  /**
   * Decoded topic array.
   */
  topics: Array<unknown>;
};

/**
 * Operation raw parameters (XDR-decoded full details).
 */
export type XdrOperationDto = {
  /**
   * Application order within the transaction (1-based, matches Horizon
   * `paging_token` convention).
   */
  application_order: number;
  /**
   * Full operation details (type-specific JSON).
   */
  details: unknown;
  /**
   * Operation type tag (e.g. `"payment"`, `"invoke_host_function"`).
   */
  op_type: string;
  /**
   * Per-operation result code from the transaction result XDR, using the
   * XDR library's variant names: `"Success"`, `"LowReserve"`, `"Trapped"`,
   * op-level rejections as `"OpNoAccount"` etc. Present on failed
   * transactions too — the failing op's code is the fail reason (task
   * 0352). `None` when the result XDR carried no per-op array
   * (validation-level failures) or was unavailable.
   */
  result_code?: string | null;
};

